import numpy as np

def rot(deg):
    t = np.deg2rad(deg)
    return np.array([[np.cos(t), -np.sin(t)], [np.sin(t), np.cos(t)]])

p, q = np.array([1.0, 0.0]), np.array([0.0, 0.0])
for deg in (0, 30, 45):
    a, b = rot(deg) @ p, rot(deg) @ q          # 좌표축을 돌린 것과 같다
    print("%2d도  L1=%.3f  L2=%.3f" % (deg, np.abs(a - b).sum(), np.linalg.norm(a - b)))

# 같은 원점 거리 1 인 점들: L1 로는 마름모, L2 로는 원
for v in [(1, 0), (0.5, 0.5), (0.707, 0.707)]:
    v = np.array(v)
    print(v, "L1=%.2f L2=%.2f" % (np.abs(v).sum(), np.linalg.norm(v)))
